INSERT INTO `evaluation_criteria` (`id`, `rater_role`, `criterion_code`, `criterion_label`, `criterion_weight`, `overall_weight`) VALUES
(1, 'student', 'STU_Q01', 'A. Teaching Clarity - The professor explains the lessons clearly.', 2.50, 50.00),
(2, 'student', 'STU_Q02', 'A. Teaching Clarity - The professor presents the subject in an organized manner.', 2.50, 50.00),
(3, 'student', 'STU_Q03', 'A. Teaching Clarity - The professor provides clear instructions for activities and assignments.', 2.50, 50.00),
(4, 'student', 'STU_Q04', 'A. Teaching Clarity - The professor uses examples that help students understand the lesson.', 2.50, 50.00),
(5, 'student', 'STU_Q05', 'A. Teaching Clarity - The professor simplifies difficult topics effectively.', 2.50, 50.00),
(6, 'student', 'STU_Q06', 'A. Teaching Clarity - The professor summarizes important points during the lesson.', 2.50, 50.00),
(7, 'student', 'STU_Q07', 'B. Engagement and Interaction - The professor encourages students to participate in discussions.', 2.50, 50.00),
(8, 'student', 'STU_Q08', 'B. Engagement and Interaction - The professor asks questions that stimulate critical thinking.', 2.50, 50.00),
(9, 'student', 'STU_Q09', 'B. Engagement and Interaction - The professor creates an interactive learning environment.', 2.50, 50.00),
(10, 'student', 'STU_Q10', 'B. Engagement and Interaction - The professor listens to students\' ideas and opinions.', 2.50, 50.00),
(11, 'student', 'STU_Q11', 'B. Engagement and Interaction - The professor motivates students to actively participate in class.', 2.50, 50.00),
(12, 'student', 'STU_Q12', 'B. Engagement and Interaction - The professor makes the class interesting and engaging.', 2.50, 50.00),
(13, 'student', 'STU_Q13', 'C. Teaching Methods - The professor uses different teaching strategies to explain the lesson.', 2.50, 50.00),
(14, 'student', 'STU_Q14', 'C. Teaching Methods - The professor uses visual aids or learning materials effectively.', 2.50, 50.00),
(15, 'student', 'STU_Q15', 'C. Teaching Methods - The professor integrates real-life examples into the lesson.', 2.50, 50.00),
